// Server-side route tables (generated by scripts/build-data.mjs into data/).
// The live feeds identify a route by an OPERATIONAL CODE that is not the public number:
//   kiosk: T5680 / T5681 -> T568,  U3000 -> 300,  T7568 -> T756,  B1000 -> SUNWAY LINE
//   GTFS-Realtime: the GTFS route_id (or a trip_id we can look up)
const fs = require('fs');
const path = require('path');

const PROVIDER_DS = { RKL: 'rkl', 'RKL-PUTRAJAYA': 'rkl', RPG: 'rpg' };
let codes = null, trips = null;
const cache = new Map();

const token = (v) => String(v == null ? '' : v).trim().toUpperCase().replace(/\s+/g, '');

/** "T5680" -> "T568", "U3000" -> "300". Anything else is returned unchanged. */
function publicNumber(value) {
  const id = token(value);
  if (/^U\d{4}$/.test(id)) return id.slice(1, -1);
  if (/^[A-Z]+\d{4}$/.test(id)) return id.slice(0, -1);
  return id;
}

function read(file) { return JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'data', file), 'utf8')); }

/** { ds, byCode:{CODE:name}, byToken:Map(token->name), names:[...] } or null for networks without bundled data. */
function datasetFor(provider) {
  const ds = PROVIDER_DS[provider];
  if (!ds) return null;
  if (!cache.has(ds)) {
    if (!codes) codes = read('codes.json');
    const c = codes[ds];
    cache.set(ds, { ds, byCode: c.byCode, names: c.names, byToken: new Map(c.names.map((n) => [token(n), n])) });
  }
  return cache.get(ds);
}
function tripsFor(ds) { if (!trips) trips = read('trips.json'); return trips[ds] || {}; }

/**
 * Feed code -> { name, known }. `known` is false when the route isn't in our catalogue
 * (new route, shuttle...): we still return a best-guess public number so the bus is never dropped.
 */
function resolveRoute(code, d) {
  const t = token(code);
  if (!t) return { name: '', known: false };
  if (d) {
    if (d.byCode[t]) return { name: d.byCode[t], known: true };            // GTFS route id / alias
    if (d.byToken.has(t)) return { name: d.byToken.get(t), known: true };  // already a public number
    const pn = publicNumber(t);
    if (d.byToken.has(pn)) return { name: d.byToken.get(pn), known: true };
    // Any route number + one trailing digit (4010 -> 401, GP020 -> GP02). Only accepted when the result is a route we know.
    if (/\d$/.test(t) && t.length > 2 && d.byToken.has(t.slice(0, -1))) return { name: d.byToken.get(t.slice(0, -1)), known: true };
  }
  return { name: publicNumber(t), known: false };
}

module.exports = { datasetFor, tripsFor, resolveRoute, publicNumber, token };
